# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs, offset=4):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: sift
def sift(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(emit(gather(digest(raw))))

